-- Migration: Create roleplay_variance_reports table
-- Created: 2025-08-28
-- Purpose: Store variance reports generated by the system

-- Create the variance reports table
CREATE TABLE IF NOT EXISTS public.roleplay_variance_reports (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  restaurant_id uuid NOT NULL,
  report_type varchar(50) NOT NULL DEFAULT 'manual',
  period_start timestamp with time zone NOT NULL,
  period_end timestamp with time zone NOT NULL,
  period_days integer NOT NULL,
  trigger_type varchar(50) NOT NULL DEFAULT 'manual',
  item_count integer NOT NULL DEFAULT 0,
  total_consumption_quantity numeric DEFAULT 0,
  total_consumption_cost numeric DEFAULT 0,
  avg_daily_consumption_cost numeric DEFAULT 0,
  total_receipts_value numeric DEFAULT 0,
  total_receipts_count integer DEFAULT 0,
  total_current_value numeric DEFAULT 0,
  report_data jsonb,
  created_at timestamp with time zone DEFAULT now(),
  created_by uuid,
  notes text,
  exported_at timestamp with time zone,
  export_format varchar(50),
  
  -- Primary key
  CONSTRAINT roleplay_variance_reports_pkey PRIMARY KEY (id),
  
  -- Foreign key to restaurants
  CONSTRAINT roleplay_variance_reports_restaurant_id_fkey 
    FOREIGN KEY (restaurant_id) 
    REFERENCES roleplay_restaurants(id) 
    ON DELETE CASCADE,
    
  -- Foreign key to users (created_by)
  CONSTRAINT roleplay_variance_reports_created_by_fkey 
    FOREIGN KEY (created_by) 
    REFERENCES roleplay_users(id) 
    ON DELETE SET NULL
);

-- Create indexes for better query performance
CREATE INDEX IF NOT EXISTS idx_roleplay_variance_reports_restaurant_id 
  ON roleplay_variance_reports(restaurant_id);

CREATE INDEX IF NOT EXISTS idx_roleplay_variance_reports_period 
  ON roleplay_variance_reports(period_start, period_end);

CREATE INDEX IF NOT EXISTS idx_roleplay_variance_reports_created_at 
  ON roleplay_variance_reports(created_at);

CREATE INDEX IF NOT EXISTS idx_roleplay_variance_reports_created_by 
  ON roleplay_variance_reports(created_by);

-- Enable Row Level Security (RLS)
ALTER TABLE roleplay_variance_reports ENABLE ROW LEVEL SECURITY;

-- Create RLS policies
-- Allow users to view reports from their restaurant
CREATE POLICY "Users can view reports from their restaurant" 
  ON roleplay_variance_reports 
  FOR SELECT 
  USING (
    EXISTS (
      SELECT 1 FROM roleplay_users 
      WHERE roleplay_users.id = auth.uid() 
      AND roleplay_users.restaurant_id = roleplay_variance_reports.restaurant_id
    )
  );

-- Allow users to create reports for their restaurant
CREATE POLICY "Users can create reports for their restaurant" 
  ON roleplay_variance_reports 
  FOR INSERT 
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM roleplay_users 
      WHERE roleplay_users.id = auth.uid() 
      AND roleplay_users.restaurant_id = roleplay_variance_reports.restaurant_id
    )
  );

-- Allow users to update reports from their restaurant
CREATE POLICY "Users can update reports from their restaurant" 
  ON roleplay_variance_reports 
  FOR UPDATE 
  USING (
    EXISTS (
      SELECT 1 FROM roleplay_users 
      WHERE roleplay_users.id = auth.uid() 
      AND roleplay_users.restaurant_id = roleplay_variance_reports.restaurant_id
    )
  );

-- Allow users to delete reports from their restaurant
CREATE POLICY "Users can delete reports from their restaurant" 
  ON roleplay_variance_reports 
  FOR DELETE 
  USING (
    EXISTS (
      SELECT 1 FROM roleplay_users 
      WHERE roleplay_users.id = auth.uid() 
      AND roleplay_users.restaurant_id = roleplay_variance_reports.restaurant_id
    )
  );

-- Grant permissions
GRANT ALL ON roleplay_variance_reports TO authenticated;
GRANT SELECT ON roleplay_variance_reports TO anon;

-- Create trigger to update updated_at timestamp if we add that column later
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Add comment to table for documentation
COMMENT ON TABLE roleplay_variance_reports IS 
'Stores variance reports generated by the inventory management system, tracking consumption and inventory changes between periods.';

COMMENT ON COLUMN roleplay_variance_reports.restaurant_id IS 'Restaurant that owns this report';
COMMENT ON COLUMN roleplay_variance_reports.report_type IS 'Type of report: manual or auto';
