COMMENT ON COLUMN roleplay_variance_reports.period_end IS 'End date of the report period';
COMMENT ON COLUMN roleplay_variance_reports.period_days IS 'Number of days in the report period';
COMMENT ON COLUMN roleplay_variance_reports.trigger_type IS 'What triggered this report: manual, snapshot, or scheduled';
COMMENT ON COLUMN roleplay_variance_reports.item_count IS 'Number of items included in the report';
COMMENT ON COLUMN roleplay_variance_reports.total_consumption_quantity IS 'Total quantity consumed during the period';
COMMENT ON COLUMN roleplay_variance_reports.total_consumption_cost IS 'Total cost of consumed items (using FIFO)';
COMMENT ON COLUMN roleplay_variance_reports.avg_daily_consumption_cost IS 'Average daily consumption cost';
COMMENT ON COLUMN roleplay_variance_reports.total_receipts_value IS 'Total value of receipts during the period';
COMMENT ON COLUMN roleplay_variance_reports.total_receipts_count IS 'Number of receipt records during the period';
COMMENT ON COLUMN roleplay_variance_reports.total_current_value IS 'Current value of inventory (using FIFO)';
COMMENT ON COLUMN roleplay_variance_reports.report_data IS 'Full report data in JSON format';
COMMENT ON COLUMN roleplay_variance_reports.created_by IS 'User who created this report';
